import{_ as s,o as a,c as t,ax as i}from"./chunks/framework.D0-oyZN4.js";const u=JSON.parse('{"title":"Authenticate","description":"Pair the Developer Studio CLI with your community using a pairing code, check the current session, and log out.","frontmatter":{"description":"Pair the Developer Studio CLI with your community using a pairing code, check the current session, and log out."},"headers":[],"relativePath":"cli/authenticate.md","filePath":"cli/authenticate.md"}'),n={name:"cli/authenticate.md"};function o(r,e,d,h,l,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/authenticate.md for this page in Markdown format</div><h1 id="authenticate" tabindex="-1">Authenticate <a class="header-anchor" href="#authenticate" aria-label="Permalink to &quot;Authenticate&quot;">​</a></h1><p>Use this guide when you need to pair <code>gsds</code> with your community for the first time, refresh an expired session, confirm which tenant you are paired with, or sign out of a shared machine.</p><h2 id="pair-a-session" tabindex="-1">Pair a session <a class="header-anchor" href="#pair-a-session" aria-label="Permalink to &quot;Pair a session&quot;">​</a></h2><p>Get a pairing code from your community:</p><ol><li>In the community admin, open <strong>Integrations</strong> from the sidebar.</li><li>Under the <strong>Developer Studio</strong> heading, choose <strong>CLI Access</strong>.</li><li>Copy the pairing code from that page.</li></ol><p>Then, in your terminal, redeem it:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PAIRING-CODE-FROM-COMMUNITY</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Pairing codes have a <strong>1-minute</strong> time-to-live, so open <strong>CLI Access</strong> with your terminal already open. If the code expires before you paste it, refresh <strong>CLI Access</strong> and try again.</p><p>On success, <code>gsds</code> stores a tenant-scoped session token that is valid for <strong>8 hours</strong>.</p><h2 id="check-the-current-session" tabindex="-1">Check the current session <a class="header-anchor" href="#check-the-current-session" aria-label="Permalink to &quot;Check the current session&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Reports which tenant the current session is bound to and whether it is still valid. Use this first whenever you see a <code>401</code> from <code>gsds preview</code> or <code>gsds connector test</code>.</p><p><code>gsds preview</code> reports a missing session and an expired one differently — see <a href="./reference/troubleshooting.html">Troubleshooting</a> for what each message means.</p><h2 id="refresh-an-expired-session" tabindex="-1">Refresh an expired session <a class="header-anchor" href="#refresh-an-expired-session" aria-label="Permalink to &quot;Refresh an expired session&quot;">​</a></h2><p>There is no refresh flow — when the 8-hour token expires, get a new pairing code from <strong>Integrations → Developer Studio → CLI Access</strong> and redeem it:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NEW-PAIRING-CODE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="log-out" tabindex="-1">Log out <a class="header-anchor" href="#log-out" aria-label="Permalink to &quot;Log out&quot;">​</a></h2><p>Clear the stored session:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logout</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Run this before handing a shared workstation to another developer, or when switching between tenants.</p><h2 id="use-multiple-tenants" tabindex="-1">Use multiple tenants <a class="header-anchor" href="#use-multiple-tenants" aria-label="Permalink to &quot;Use multiple tenants&quot;">​</a></h2><p>Each community you pair with is a separate <strong>tenant</strong>. Logging into a second tenant does not replace your first session. Each <code>gsds login</code> keeps its own <strong>profile</strong>, keyed by tenant, and whichever one you just logged into becomes current — every other command uses the current profile automatically.</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # list stored profiles, marks the current one and any needing a re-login</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # switch which one is current</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>gsds profile</code> marks a profile whose session has timed out <code>(expired)</code>, and one whose stored credential is present but cannot be read back — corrupted, hand-edited, or restored from a backup — <code>(unreadable)</code>. Markers combine, so the current profile can itself be expired and shows as <code>(current, expired)</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>acme-en (current)</span></span>
<span class="line"><span>acme-eu (expired)</span></span>
<span class="line"><span>acme-sandbox (unreadable)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>An expired profile stays stored and stays switchable — it is the name to log back in under, so nothing is dropped from the list.</p><p><code>gsds logout</code> promotes another profile to current when one remains, preferring one that is neither expired nor unreadable, and tells you when the one it promoted still needs a new login.</p><p>Pass <code>--profile &lt;name&gt;</code> on <code>gsds login</code>, <code>gsds preview</code>, <code>gsds logout</code>, or <code>gsds connector test</code> when you want to name a profile explicitly — for example logging into the same tenant twice under different names — or target a profile other than the current one for a single command without switching it.</p><h2 id="use-the-same-account-as-your-community-session" tabindex="-1">Use the same account as your community session <a class="header-anchor" href="#use-the-same-account-as-your-community-session" aria-label="Permalink to &quot;Use the same account as your community session&quot;">​</a></h2><p><code>gsds preview</code> registers its preview session against the account that redeemed the pairing code. The No-Code Builder then looks for a preview session belonging to the account you are signed in as, so the two have to be the same person.</p><p>A session paired under a different account on the same tenant — a colleague&#39;s login, or a second account of your own — is not visible to you in the builder, and your local widgets never appear there. <code>gsds login --status</code> reports which session is current.</p><h2 id="where-the-session-is-stored" tabindex="-1">Where the session is stored <a class="header-anchor" href="#where-the-session-is-stored" aria-label="Permalink to &quot;Where the session is stored&quot;">​</a></h2><p><code>gsds</code> writes the session token to your OS keychain, one account per profile, with a file-based fallback when no keychain is available. See <a href="./reference/project-files.html#in-your-user-account">Project Files</a> for the full storage rules and paths.</p><h2 id="commands-that-require-a-session" tabindex="-1">Commands that require a session <a class="header-anchor" href="#commands-that-require-a-session" aria-label="Permalink to &quot;Commands that require a session&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Why it needs a session</th></tr></thead><tbody><tr><td><code>gsds preview</code></td><td>Registers a preview session with your community so local widgets appear in the picker, for the account that paired it</td></tr><tr><td><code>gsds connector test</code></td><td>Runs against the paired tenant</td></tr></tbody></table><p>Every other command works without a session.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Test a Connector against the paired tenant in <a href="./test-connectors.html">Test Connectors</a></li><li>Run <code>gsds</code> unattended in CI or from an AI agent with <a href="./automate-with-ci-and-ai.html">Automate with CI and AI</a></li><li>Look up flags for the login commands in the <a href="./reference/commands.html">Command reference</a></li></ul>`,39)])])}const g=s(n,[["render",o]]);export{u as __pageData,g as default};
